package com.nigson.commerce.affiliate;

import java.time.*;
import java.util.*;
import java.sql.Timestamp;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import com.nigson.commerce.pricing.PricingAuthority;
import com.nigson.commerce.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ActorAssertion;
import tools.jackson.databind.JsonNode;

/** Affiliate links are separate from first-purchase customer referral rewards. */
public final class AffiliateLinks {
 public record Status(String state){}
 public record Link(String code,UUID productId,String path){}
 public record Visit(UUID id,UUID productId,boolean attributed){}
 private final JdbcTemplate jdbc;private final PricingAuthority authority;private final PlatformStore commands;private final AuditWriter audit;private final Clock clock;private final TransactionTemplate tx;
 private long second=-1;private int calls;
 public AffiliateLinks(JdbcTemplate jdbc,PricingAuthority authority,PlatformStore commands,AuditWriter audit,Clock clock,PlatformTransactionManager manager){this.jdbc=jdbc;this.authority=authority;this.commands=commands;this.audit=audit;this.clock=clock;tx=new TransactionTemplate(manager);tx.setTimeout(3);}
 private synchronized void admit(){long time=clock.instant().getEpochSecond();if(time!=second){second=time;calls=0;}if(++calls>100)throw new Problem.Failure(ProblemCode.RATE_LIMITED);}
 private static List<String> access(JdbcTemplate jdbc,UUID party,boolean lock){return jdbc.query("SELECT e.status FROM commerce.account_entitlement e JOIN commerce.organization o ON o.id=e.organization_id JOIN commerce.organization_membership m ON m.organization_id=o.id JOIN commerce.party p ON p.id=m.party_id WHERE m.party_id=? AND e.entitlement='AFFILIATE_MARKETING' AND e.partner_type='AFFILIATE' AND m.status='ACTIVE' AND o.status='ACTIVE' AND p.status='ACTIVE'"+(lock?" FOR SHARE OF e,o,m":""),(r,n)->r.getString(1),party);}
 public Status status(ActorAssertion.Actor actor){authority.require(actor,"CUSTOMER");if(authority.phase()<3)return new Status("NONE");return tx.execute(s->{var states=access(jdbc,actor.party(),false);return new Status(states.size()==1&&Set.of("ACTIVE","SUSPENDED").contains(states.getFirst())?states.getFirst():"NONE");});}
 public Link link(ActorAssertion.Actor actor,UUID product,String key,UUID correlation){authority.require(actor,"CUSTOMER");if(authority.phase()<3)throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);ApiValues.idempotencyKey(key);PlatformStore.Response result;try{result=commands.executeLocal(actor.party().toString(),"API-223",key,EventCodec.JSON.valueToTree(Map.of("productId",product)),db->{authority.stabilize(actor,"CUSTOMER");var states=access(jdbc,actor.party(),true);if(states.size()!=1||!states.getFirst().equals("ACTIVE"))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM commerce.product p JOIN commerce.product_market_eligibility e ON e.product_id=p.id JOIN commerce.market m ON m.id=e.market_id WHERE p.id=? AND p.status='ACTIVE' AND p.deleted_at IS NULL AND e.eligible AND m.code='NG' AND m.enabled)",Boolean.class,product)))throw new Problem.Failure(ProblemCode.NOT_FOUND);UUID id=UUID.randomUUID();int created=jdbc.update("INSERT INTO commerce.affiliate_link(id,created_by,updated_by,party_id,product_id,code) VALUES (?,?,?,?,?,?) ON CONFLICT(party_id,product_id) DO NOTHING",id,actor.party().toString(),actor.party().toString(),actor.party(),product,UUID.randomUUID().toString().replace("-",""));String code=jdbc.queryForObject("SELECT code FROM commerce.affiliate_link WHERE party_id=? AND product_id=?",String.class,actor.party(),product);if(created==1)audit.append(actor.party().toString(),AuditValues.ActorKind.USER,AuditValues.Action.REFERRAL_CODE_CREATE,AuditValues.Resource.REFERRAL,id,correlation,AuditValues.Reason.OPERATOR_REQUEST,null,Map.of("productId",product),null);return new PlatformStore.Response(200,EventCodec.JSON.valueToTree(new Link(code,product,"/api/v1/affiliate-links/"+code)),product);});}catch(PlatformStore.Conflict conflict){throw new Problem.Failure(conflict.getMessage().equals("IDEMPOTENCY_HASH_MISMATCH")?ProblemCode.IDEMPOTENCY_HASH_MISMATCH:ProblemCode.IDEMPOTENCY_IN_PROGRESS);}
  // Replays recheck current access too: suspension never exposes a fresh usable link.
  if(!status(actor).state().equals("ACTIVE"))throw new Problem.Failure(ProblemCode.ACCESS_DENIED);return EventCodec.JSON.treeToValue(result.body(),Link.class);
 }
 public Visit visit(String code,UUID previous){admit();if(authority.phase()<3)throw new Problem.Failure(ProblemCode.FEATURE_DISABLED);if(code==null||!code.matches("[a-f0-9]{32}"))throw ApiValues.invalid();return tx.execute(s->{var rows=jdbc.query("SELECT l.id,l.product_id,l.party_id FROM commerce.affiliate_link l JOIN commerce.product p ON p.id=l.product_id WHERE l.code=? AND p.status='ACTIVE' AND p.deleted_at IS NULL",(r,n)->new UUID[]{r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,UUID.class)},code);if(rows.size()!=1)throw new Problem.Failure(ProblemCode.NOT_FOUND);var row=rows.getFirst();var states=access(jdbc,row[2],true);if(states.size()!=1||!states.getFirst().equals("ACTIVE"))return new Visit(null,row[1],false);UUID visit=previous==null?UUID.randomUUID():previous;Instant now=clock.instant();jdbc.update("INSERT INTO commerce.affiliate_visit(id,created_by,updated_by,link_id,clicked_at,expires_at) VALUES (?,'affiliate-visit','affiliate-visit',?,?,?) ON CONFLICT(id) DO UPDATE SET link_id=EXCLUDED.link_id,clicked_at=EXCLUDED.clicked_at,expires_at=EXCLUDED.expires_at,version=commerce.affiliate_visit.version+1,updated_at=now()",visit,row[0],Timestamp.from(now),Timestamp.from(now.plus(Duration.ofDays(7))));jdbc.update("DELETE FROM commerce.affiliate_visit WHERE id IN(SELECT id FROM commerce.affiliate_visit WHERE expires_at<? ORDER BY expires_at LIMIT 100)",Timestamp.from(now));return new Visit(visit,row[1],true);});}
 /** Called inside checkout's existing transaction; result becomes an immutable order snapshot. */
 public static JsonNode attribution(JdbcTemplate jdbc,int phase,UUID visit,UUID buyer,UUID organization,Instant now){if(phase<3||visit==null||organization!=null)return null;var rows=jdbc.query("SELECT l.party_id,l.id,l.product_id,v.clicked_at,v.expires_at FROM commerce.affiliate_visit v JOIN commerce.affiliate_link l ON l.id=v.link_id WHERE v.id=? AND v.expires_at>? AND v.clicked_at<=?",(r,n)->new Object[]{r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,UUID.class),r.getTimestamp(4).toInstant(),r.getTimestamp(5).toInstant()},visit,Timestamp.from(now),Timestamp.from(now));if(rows.size()!=1||buyer.equals(rows.getFirst()[0]))return null;var row=rows.getFirst();var states=access(jdbc,(UUID)row[0],true);if(states.size()!=1||!states.getFirst().equals("ACTIVE"))return null;return EventCodec.JSON.valueToTree(Map.of("visitId",visit,"affiliatePartyId",row[0],"linkId",row[1],"productId",row[2],"clickedAt",row[3],"expiresAt",row[4],"commissionRate","0.05","holdDays",7));}
}
